<script setup lang="ts">
import {ref,reactive,computed,onUnmounted} from 'vue';
import {onLoad,onShow,onHide} from '@dcloudio/uni-app';
import {request,login,attachFile,downloadFile,type User,type Item,type Message} from '../../services/api';
const user=ref<User|null>(null),items=ref<Item[]>([]),messages=ref<Message[]>([]),page=ref('notes'),inboxReturn=ref('reminders'),ready=ref(false),error=ref(''),query=ref(''),scope=ref('all'),category=ref('待办'),code=ref(''),inviter=ref(''),nickname=ref(''),agree=ref(false),keyboardOpen=ref(false);
const pending=reactive<Record<string,boolean>>({});
const today=new Date().toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'});
async function addAttachment(){await act('attachment',async()=>{if((draft.value.attachments||[]).length>=10)throw new Error('最多 10 个附件');const f=await attachFile();draft.value.attachments=[...(draft.value.attachments||[]),f]})}
const empty=(kind:'note'|'reminder'='note'):Item=>({kind,title:'',content:'',links:[],scope:'mine',repeat:'none',recipient:'me',advance:0,done:false});
const draft=ref<Item>(empty()),linkText=ref(''),date=ref(''),time=ref('19:00');
const tabs=[
 {key:'notes',name:'随记',icon:'/static/nav-icons/note-inactive.png',activeIcon:'/static/nav-icons/note-active.png'},
 {key:'reminders',name:'提醒',icon:'/static/nav-icons/bell-inactive.png',activeIcon:'/static/nav-icons/bell-active.png'},
 {key:'us',name:'我们',icon:'/static/nav-icons/heart-inactive.png',activeIcon:'/static/nav-icons/heart-active.png'}
];
const list=computed(()=>items.value.filter(i=>i.kind===(page.value==='reminders'?'reminder':'note')&&(scope.value==='all'||i.scope===scope.value)&&(!query.value||(i.title+' '+i.content).includes(query.value))).sort((a,b)=>Number(!!b.pinned)-Number(!!a.pinned)||(b.updatedAt||'').localeCompare(a.updatedAt||'')));
const unread=computed(()=>messages.value.filter(m=>!m.seen).length);
let timer:ReturnType<typeof setInterval>|undefined;
function alertError(e:unknown){error.value=e instanceof Error?e.message:'操作失败';uni.showToast({title:error.value,icon:'none'})}
async function act(key:string,fn:()=>Promise<void>){if(pending[key])return;pending[key]=true;error.value='';try{await fn()}catch(e){alertError(e)}finally{pending[key]=false}}
async function refresh(){if(!uni.getStorageSync('session')){user.value=null;return}try{const [u,i,m]=await Promise.all([request<User>('/me'),request<Item[]>('/items'),request<Message[]>('/notifications')]);user.value=u;nickname.value=u.nickname;items.value=i;messages.value=m}catch(e){if(!uni.getStorageSync('session'))user.value=null;throw e}}
async function signIn(){await act('login',async()=>{if(!agree.value)throw new Error('请先确认数据使用说明');user.value=await login();await refresh()})}
function switchPage(key:string){page.value=key;scope.value='all';query.value='';error.value=''}
function edit(item?:Item){draft.value=item?JSON.parse(JSON.stringify(item)):empty(page.value==='reminders'?'reminder':'note');linkText.value=draft.value.links.join('\n');const d=draft.value.nextAt?new Date(draft.value.nextAt):new Date(Date.now()+3600000);date.value=[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');time.value=String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0');page.value='editor'}
function detail(item:Item){draft.value=JSON.parse(JSON.stringify(item));page.value='detail'}
async function save(){await act('save',async()=>{if(!draft.value.title.trim())throw new Error('请填写标题');draft.value.links=linkText.value.split('\n').map(s=>s.trim()).filter(Boolean);if(draft.value.links.some(s=>!/^https?:\/\//.test(s)))throw new Error('链接需要以 https:// 或 http:// 开头');if(draft.value.kind==='reminder')draft.value.nextAt=new Date(date.value+'T'+time.value+':00').toISOString();await request(draft.value.id?'/items/'+draft.value.id:'/items',draft.value.id?'PUT':'POST',draft.value);switchPage(draft.value.kind==='note'?'notes':'reminders');await refresh();uni.showToast({title:'已保存',icon:'success'})})}
async function remove(){uni.showModal({title:'删除这条内容？',content:'删除后无法恢复。',success:r=>{if(r.confirm)act('delete:'+draft.value.id,async()=>{await request('/items/'+draft.value.id,'DELETE');switchPage(draft.value.kind==='note'?'notes':'reminders');await refresh()})}})}
async function toggle(i:Item){await act('toggle:'+i.id,async()=>{await request('/items/'+i.id,'PUT',{...i,done:!i.done});await refresh()})}
async function invite(){await act('invite',async()=>{const r=await request<{code:string}>('/invite','POST');code.value=r.code;inviter.value='';page.value='invite'})}
async function checkInvite(){await act('preview-invite',async()=>{const r=await request<{nickname:string}>('/invite/preview','POST',{code:code.value});inviter.value=r.nickname})}
async function accept(){await act('accept-invite',async()=>{await request('/invite/accept','POST',{code:code.value});await refresh();page.value='us';code.value='';inviter.value=''})}
async function backToUs(){page.value='us';await act('refresh-us',refresh)}
async function saveNickname(){await act('nickname',async()=>{await request('/me','PUT',{nickname:nickname.value});await refresh()})}
async function logout(){await act('logout',async()=>{await request('/logout','POST');clearSession()})}
function copy(value:string){uni.setClipboardData({data:value})}
function recipientChange(e:any){draft.value.recipient=['me','partner','both'][Number(e.detail.value)];if(draft.value.recipient!=='me')draft.value.scope='shared'}
function setPinned(e:any){draft.value.pinned=e.detail.value}
function clearSession(){uni.removeStorageSync('session');user.value=null;items.value=[];messages.value=[];page.value='notes'}
function format(v?:string){return v?new Date(v).toLocaleString('zh-CN',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'}):''}
async function inbox(){inboxReturn.value=page.value==='us'?'us':'reminders';page.value='inbox';await act('inbox',async()=>{await request('/notifications/read','POST');await refresh()})}
function closeInbox(){page.value=inboxReturn.value}
function start(){clearInterval(timer);timer=setInterval(()=>{if(user.value)refresh().catch(()=>{})},30000)}
onLoad(async()=>{try{await refresh()}catch(e){alertError(e)}finally{ready.value=true}});onShow(()=>{start();if(ready.value)refresh().catch(alertError)});onHide(()=>clearInterval(timer));onUnmounted(()=>clearInterval(timer));
</script>
<template>
<view class="shell">
 <view class="header"><text class="brand">小记 <text class="brand-sub">TOGETHER</text></text><button v-if="user" class="profile" :class="{paired:!!user.partner}" aria-label="打开我们的小空间" @click="switchPage('us')">{{user.nickname.slice(0,1)}}<text v-if="user.partner"> · {{user.partner.nickname.slice(0,1)}}</text></button></view>
 <view v-if="!ready" class="empty">正在打开小记…</view>
 <view v-else-if="!user" class="login">
  <view class="logo-mark">小记</view><text class="headline">生活里的小事，<br/>一起记得。</text><text class="muted block">随手留下，也在合适的时候提醒你。</text>
  <view class="login-card"><text class="section-title">欢迎来到小记</text><text class="muted block">首次登录将自动创建账号</text><!-- #ifdef MP-WEIXIN --><button class="primary" :disabled="pending.login" @click="signIn"><view v-if="pending.login" class="button-spinner"/><text>{{pending.login?'登录中…':'微信登录'}}</text></button><!-- #endif --><!-- #ifndef MP-WEIXIN --><view class="platform-tip">请在微信小程序中打开并登录</view><!-- #endif --><view class="consent" @click="agree=!agree"><text class="check" :class="{checked:agree}"/><text>我知悉：内容存储在本服务，私人备忘仅自己可见；选择共享后另一半可查看和编辑。</text></view></view>
 </view>
 <template v-else>
 <view v-if="['notes','reminders'].includes(page)">
  <view class="eyebrow">{{today}}<text>{{user.partner?'我们的双人空间':'我的小空间'}}</text></view><text class="headline">{{page==='notes'?'随手记下。':'别忘了这些小事。'}}</text><text class="muted block">{{page==='notes'?'你的想法，我们的日常。':'待办有安排，生活有期待。'}}</text>
  <input class="search" v-model="query" placeholder="搜索标题或内容" @focus="keyboardOpen=true" @blur="keyboardOpen=false"/>
  <view v-if="page==='notes'" class="filters"><button v-for="s in [{k:'all',n:'全部'},{k:'mine',n:'私人'},{k:'shared',n:'我们俩'}]" :key="s.k" :aria-pressed="scope===s.k" :class="{active:scope===s.k}" @click="scope=s.k">{{s.n}}</button></view>
  <view v-else class="filters reminder-filters"><button v-for="c in ['待办','比赛','新闻']" :key="c" :aria-pressed="category===c" :class="{active:category===c}" @click="category=c">{{c}}</button><button aria-label="打开站内消息" @click="inbox">消息</button></view>
  <view v-if="page==='reminders'&&category!=='待办'" class="empty"><text class="section-title">{{category==='比赛'?'关注喜欢的比赛':'每天一份关心的新闻'}}</text><text class="muted block">{{category==='比赛'?'赛程数据源尚未接入，可以先手动创建开赛提醒。':'新闻订阅尚未接入，可以先保存新闻链接。'}}</text><button class="primary" @click="edit()">创建时间提醒</button></view>
  <template v-else><view v-if="!list.length" class="empty"><text class="section-title">{{query?'没有找到相关内容':'从第一件小事开始'}}</text><text class="muted block">{{query?'换个关键词试试。':'点击右下角，记下你想记住的。'}}</text></view>
  <view v-for="i in list" :key="i.id" class="card" :class="{butter:i.pinned,completed:i.done}" @click="detail(i)"><view class="card-meta"><text>{{i.scope==='shared'?'我们俩':'仅自己'}}{{i.pinned?' · 置顶':''}}</text><text>{{i.kind==='reminder'?format(i.nextAt):format(i.updatedAt)}}</text></view><view class="row"><text class="card-title">{{i.title}}</text><button v-if="i.kind==='reminder'" class="done" :disabled="pending['toggle:'+i.id]" :aria-label="i.done?'标记为待办':'标记为完成'" @click.stop="toggle(i)"><view v-if="pending['toggle:'+i.id]" class="button-spinner status-spinner"/><view v-else class="status-icon" :class="{checked:i.done}"/></button></view><text v-if="i.content" class="excerpt">{{i.content}}</text><text class="muted small block">{{i.kind==='note'?(i.links.length?'附 '+i.links.length+' 个链接':'文字备忘'):(i.done?'已完成':({none:'单次',daily:'每天',weekly:'每周'} as any)[i.repeat||'none']+' · 站内提醒')}}</text></view></template>
 </view>
 <view v-else-if="page==='detail'" class="detail-page"><view class="subnav"><button class="back" @click="switchPage(draft.kind==='note'?'notes':'reminders')"><view class="back-icon"/><text>返回</text></button><text class="badge">{{draft.scope==='shared'?'我们俩':'仅自己'}}</text></view><text class="headline">{{draft.title}}</text><text class="body-text">{{draft.content||'暂无正文'}}</text><view v-if="draft.kind==='reminder'" class="card"><text>提醒时间：{{format(draft.nextAt)}}</text><text class="muted block">提前 {{draft.advance}} 分钟 · {{draft.done?'已完成':'待提醒'}}</text></view><view v-for="f in draft.attachments" :key="f.id" class="link" @click="act('download:'+f.id,async()=>{await downloadFile(f)})">附件 · {{f.name}}<text class="muted block">{{pending['download:'+f.id]?'正在打开…':'点击下载 / 打开'}}</text></view><view v-for="link in draft.links" :key="link" class="link" @click="copy(link)">{{link}}<text class="muted block">点击复制链接</text></view><view class="actions"><button class="primary" @click="edit(draft)">编辑</button><button v-if="draft.owner===user.id" class="danger" :disabled="pending['delete:'+draft.id]" @click="remove"><view v-if="pending['delete:'+draft.id]" class="button-spinner"/><text>{{pending['delete:'+draft.id]?'删除中…':'删除'}}</text></button></view></view>
 <view v-else-if="page==='editor'" class="form editor-page"><button class="back" @click="switchPage(draft.kind==='note'?'notes':'reminders')"><view class="back-icon"/><text>返回</text></button><text class="headline">{{draft.id?'编辑':draft.kind==='note'?'记一笔。':'添加提醒。'}}</text><text class="label">标题</text><input v-model="draft.title" maxlength="100" placeholder="想记下什么？"/><text class="label">内容</text><textarea v-model="draft.content" maxlength="50000" placeholder="文字、清单，或者想对她说的话…" disable-default-padding/><text class="label">链接（每行一个）</text><textarea class="links-input" v-model="linkText" placeholder="https://…" disable-default-padding/><text class="label">附件</text><view v-for="(f,index) in draft.attachments" :key="f.id" class="setting"><text>{{f.name}}</text><button @click="draft.attachments?.splice(index,1)">移除</button></view><button class="attachment-button" :disabled="pending.attachment" @click="addAttachment"><view v-if="pending.attachment" class="button-spinner"/><view v-else class="mini-plus-icon"/><text>{{pending.attachment?'选择中…':'添加附件'}}</text></button><text class="muted small block">单个最大 12MB，最多 10 个；App 当前可选择图片。</text><text class="label">可见范围</text><view v-if="draft.owner&&draft.owner!==user.id" class="picker picker-readonly"><text>我们俩 · 共同编辑</text><text class="muted small">创建者管理范围</text></view><picker v-else :range="['仅自己','我们俩']" :value="draft.scope==='shared'?1:0" @change="draft.scope=Number($event.detail.value)?'shared':'mine'"><view class="picker"><text>{{draft.scope==='shared'?'我们俩 · 共同编辑':'仅自己可见'}}</text><view class="chevron-down"/></view></picker><text v-if="draft.owner&&draft.owner!==user.id" class="muted small block">只有创建者可以把共享内容改为私人。</text><text v-else-if="!user.partner" class="muted small block">绑定另一半后可以共享</text>
 <template v-if="draft.kind==='reminder'"><text class="label">提醒时间</text><view class="actions"><picker mode="date" :value="date" @change="date=$event.detail.value"><view class="picker">{{date}}</view></picker><picker mode="time" :value="time" @change="time=$event.detail.value"><view class="picker">{{time}}</view></picker></view><text class="label">重复</text><picker :range="['不重复','每天','每周']" :value="['none','daily','weekly'].indexOf(draft.repeat||'none')" @change="draft.repeat=['none','daily','weekly'][Number($event.detail.value)]"><view class="picker"><text>{{({none:'不重复',daily:'每天',weekly:'每周'} as any)[draft.repeat||'none']}}</text><view class="chevron-down"/></view></picker><text class="label">提前多久</text><picker :range="['准时','15 分钟','30 分钟','1 小时']" :value="[0,15,30,60].indexOf(draft.advance||0)" @change="draft.advance=[0,15,30,60][Number($event.detail.value)]"><view class="picker"><text>{{draft.advance?draft.advance+' 分钟':'准时'}}</text><view class="chevron-down"/></view></picker><text class="label">提醒谁</text><picker :range="draft.owner&&draft.owner!==user.id?['创建者','创建者的另一半','我们俩']:['我','另一半','我们俩']" :value="['me','partner','both'].indexOf(draft.recipient||'me')" @change="recipientChange"><view class="picker"><text>{{draft.owner&&draft.owner!==user.id?({me:'创建者',partner:'创建者的另一半',both:'我们俩'} as any)[draft.recipient||'me']:({me:'我',partner:'另一半',both:'我们俩'} as any)[draft.recipient||'me']}}</text><view class="chevron-down"/></view></picker><text class="muted small block">当前提供站内消息，关闭应用后不会弹出系统通知。</text></template>
 <view v-else class="setting"><text>置顶这条备忘</text><switch color="#b28b35" :checked="draft.pinned" @change="setPinned"/></view><button class="primary" :disabled="pending.save" @click="save"><view v-if="pending.save" class="button-spinner"/><text>{{pending.save?'保存中…':'保存'}}</text></button></view>
 <view v-else-if="page==='us'" class="us-page"><text class="headline">我们的小空间。</text><text class="muted block">有各自的小记，也有一起的日常。</text><view class="couple"><view class="avatar">{{user.nickname.slice(0,1)}}</view><image class="couple-heart" src="/static/nav-icons/heart-active.png" mode="aspectFit"/><view class="avatar">{{user.partner?user.partner.nickname.slice(0,1):'?'}}</view></view><text class="section-title">{{user.nickname}}{{user.partner?' ＆ '+user.partner.nickname:'，等一个人加入'}}</text><view v-if="!user.partner" class="card pair-card"><text>绑定后，一起记录和提醒。</text><view class="actions"><button class="primary" :disabled="pending.invite" @click="invite"><view v-if="pending.invite" class="button-spinner"/><text>{{pending.invite?'生成中…':'邀请另一半'}}</text></button><button @click="code='';inviter='';page='join'">输入邀请码</button></view></view><view v-else class="card butter"><view class="bound-title"><text class="section-title">已经绑定</text><image src="/static/nav-icons/heart-active.png" mode="aspectFit"/></view><text class="muted block">私人备忘不会自动共享。</text></view><view class="form profile-form"><text class="label">我的昵称</text><input v-model="nickname" maxlength="20" @focus="keyboardOpen=true" @blur="keyboardOpen=false"/><button class="nickname-save" :disabled="pending.nickname" @click="saveNickname"><view v-if="pending.nickname" class="button-spinner"/><text>{{pending.nickname?'保存中…':'保存昵称'}}</text></button></view><button class="logout" :disabled="pending.logout" @click="logout"><view v-if="pending.logout" class="button-spinner"/><text>{{pending.logout?'退出中…':'退出登录'}}</text></button></view>
 <view v-else-if="page==='invite'" class="simple-page"><button class="back" @click="backToUs"><view class="back-icon"/><text>返回</text></button><text class="headline">把小记分享给她。</text><text class="muted block">把邀请码发给另一半，对方登录后输入并确认。</text><view class="card butter"><text class="invite-code">{{code}}</text><text class="muted block">24 小时内有效 · 仅可使用一次</text></view><button class="primary" @click="copy(code)">复制邀请码</button><text class="muted block">对方确认后，返回“我们”即可看到绑定结果。</text></view>
 <view v-else-if="page==='join'" class="form simple-page"><button class="back" @click="page='us'"><view class="back-icon"/><text>返回</text></button><text class="headline">加入彼此的日常。</text><text class="label">另一半的邀请码</text><input v-model="code" maxlength="12" placeholder="输入 12 位邀请码" @input="inviter=''"/><button class="primary" :disabled="pending['preview-invite']" @click="checkInvite"><view v-if="pending['preview-invite']" class="button-spinner"/><text>{{pending['preview-invite']?'查询中…':'查看邀请'}}</text></button><view v-if="inviter" class="card butter"><text class="section-title">{{inviter}} 邀请你绑定</text><text class="muted block">确认后可使用双人共享备忘和提醒。</text><button class="primary" :disabled="pending['accept-invite']" @click="accept"><view v-if="pending['accept-invite']" class="button-spinner"/><text>{{pending['accept-invite']?'绑定中…':'确认绑定'}}</text></button></view></view>
 <view v-else-if="page==='inbox'" class="simple-page"><button class="back" @click="closeInbox"><view class="back-icon"/><text>返回</text></button><text class="headline">到时间了。</text><view v-if="!messages.length" class="empty">暂时没有提醒消息</view><view v-for="m in messages" :key="m.id" class="card"><text class="card-title">{{m.title}}</text><text class="muted block">{{format(m.due)}}</text></view></view>
 <view v-if="['notes','reminders','us'].includes(page)&&!keyboardOpen" class="floating"><view class="dock"><button v-for="t in tabs" :key="t.key" :aria-label="t.name+(t.key==='reminders'&&unread?'，'+unread+' 条未读':'')" :aria-current="page===t.key?'page':undefined" :class="{selected:page===t.key}" @click="switchPage(t.key)"><view class="tab-icon-wrap"><image class="nav-icon" :src="page===t.key?t.activeIcon:t.icon" mode="aspectFit"/><text v-if="t.key==='reminders'&&unread" class="nav-badge">{{unread>99?'99+':unread}}</text></view><text v-if="page===t.key" class="nav-label">{{t.name}}</text></button></view><button class="add" aria-label="新建" @click="edit()"><view class="plus-icon"/></button></view>
 </template><text v-if="error" class="error">{{error}}</text>
</view>
</template>
